changeSet.sql:
ALTER TABLE produto_nutricional ADD CONSTRAINT ck_produto_nutricional_papel
CHECK (papel_artesanal IS NULL
       OR papel_artesanal IN ('BASE', 'CARBOIDRATO', 'PROTEINA', 'LIPIDIO'));

ALTER TABLE produto_nutricional ADD CONSTRAINT ck_produto_nutricional_papel_coerente
CHECK ((tipo = 'INSUMO_ARTESANAL' AND papel_artesanal IS NOT NULL)
       OR (tipo <> 'INSUMO_ARTESANAL' AND papel_artesanal IS NULL));

ALTER TABLE produto_nutricional ADD CONSTRAINT ck_produto_nutricional_calculavel
CHECK (tipo = 'SUPLEMENTO_ORAL'
       OR (kcal IS NOT NULL AND proteina_g IS NOT NULL AND medida_qtd > 0));
